package checker

import (
	"github.com/microsoft/typescript-go/internal/ast"
	"slices"
)

type InterfaceSignatureOwnerControl struct {
	Counts                                                                                              []int
	DistinctOwners, DistinctDeclaredTypes, RepeatTypes, DeclarationKeys, OppositeEmpty, RawUnredirected bool
}

func (c *Checker) QualifyInterfaceSignatureOwners(file *ast.SourceFile, kind SignatureKind) InterfaceSignatureOwnerControl {
	raw := c.getSymbolOfDeclaration(file.Statements.Nodes[0])
	extra := file.Statements.Nodes[1]
	original := c.getDeclaredTypeOfSymbol(raw)
	head := c.cloneTypeAsModuleType(raw, original, nil)
	twin := c.cloneTypeAsModuleType(raw, original, nil)
	head.Declarations = append(head.Declarations, extra)
	// Complete the private declared-member slot before its first read.
	// An owner declaration alone does not update native signature members.
	key := ast.InternalSymbolNameCall
	if kind == SignatureKindConstruct {
		key = ast.InternalSymbolNameNew
	}
	slot := head.Members[key]
	privateSlot := c.newSymbol(slot.Flags, slot.Name)
	privateSlot.Declarations = append(slices.Clone(slot.Declarations), extra.Members()[0])
	privateSlot.Parent = slot.Parent
	privateSlot.ValueDeclaration = slot.ValueDeclaration
	head.Members[key] = privateSlot
	row := InterfaceSignatureOwnerControl{DistinctOwners: raw != head && raw != twin && head != twin, RepeatTypes: true, DeclarationKeys: true, OppositeEmpty: true, RawUnredirected: c.getMergedSymbol(raw) == raw}
	ht := c.getDeclaredTypeOfSymbol(head)
	tt := c.getDeclaredTypeOfSymbol(twin)
	row.DistinctDeclaredTypes = original != ht && original != tt && ht != tt
	opposite := SignatureKindCall
	if kind == SignatureKindCall {
		opposite = SignatureKindConstruct
	}
	for _, owner := range []*ast.Symbol{twin, head, raw, head, twin} {
		typ := c.getDeclaredTypeOfSymbol(owner)
		row.RepeatTypes = row.RepeatTypes && c.getDeclaredTypeOfSymbol(owner) == typ
		signatures := c.getSignaturesOfType(typ, kind)
		row.Counts = append(row.Counts, len(signatures))
		if owner == head {
			row.DeclarationKeys = row.DeclarationKeys && len(signatures) == 2 && signatures[1].declaration == extra.Members()[0]
		}
		row.OppositeEmpty = row.OppositeEmpty && len(c.getSignaturesOfType(typ, opposite)) == 0
	}
	return row
}

