package main

import (
	"context"
	"encoding/json"
	"fmt"
	"github.com/microsoft/typescript-go/internal/bundled"
	"github.com/microsoft/typescript-go/internal/checker"
	"github.com/microsoft/typescript-go/internal/compiler"
	"github.com/microsoft/typescript-go/internal/core"
	"github.com/microsoft/typescript-go/internal/tsoptions"
	"github.com/microsoft/typescript-go/internal/vfs/vfstest"
	"slices"
)

func main() {
	for _, checkedFirst := range []bool{false, true} {
		for _, construct := range []bool{false, true} {
			member := "(x: number): number;"
			kind := checker.SignatureKindCall
			if construct {
				member = "new (x: number): number;"
				kind = checker.SignatureKindConstruct
			}
			source := "interface Owner { " + member + " } interface Extra { " + member + " }"
			fs := vfstest.FromMap(map[string]string{"/main.ts": source, "/tsconfig.json": `{"compilerOptions":{"strict":true,"singleThreaded":true,"noEmit":true,"target":"es2020"},"files":["main.ts"]}`}, true)
			host := compiler.NewCompilerHost("/", bundled.WrapFS(fs), bundled.LibPath(), nil, nil)
			config, errs := tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json", &core.CompilerOptions{}, nil, host, nil)
			if len(errs) != 0 {
				panic(errs)
			}
			program := compiler.NewProgram(compiler.ProgramOptions{Config: config, Host: host})
			program.BindSourceFiles()
			c, done := program.GetTypeChecker(context.Background())
			file := program.GetSourceFile("/main.ts")
			if checkedFirst {
				if d := c.GetDiagnostics(context.Background(), file); len(d) != 0 {
					panic(d)
				}
			}
			row := c.QualifyInterfaceSignatureOwners(file, kind)
			if !slices.Equal(row.Counts, []int{1, 2, 1, 2, 1}) || !row.DistinctOwners || !row.DistinctDeclaredTypes || !row.RepeatTypes || !row.DeclarationKeys || !row.OppositeEmpty || !row.RawUnredirected {
				panic(fmt.Sprintf("unexpected selected owners: %+v", row))
			}
			if d := c.GetDiagnostics(context.Background(), file); len(d) != 0 {
				panic(d)
			}
			output, err := json.Marshal(map[string]any{"checkedFirst": checkedFirst, "construct": construct, "row": row})
			if err != nil {
				panic(err)
			}
			fmt.Println(string(output))
			done()
		}
	}
}

